CREATE TABLE IF NOT EXISTS patient ( id INTEGER PRIMARY KEY CHECK (id = 1), name TEXT NOT NULL, date_of_birth TEXT NOT NULL , surname TEXT DEFAULT "", username TEXT DEFAULT "", sync_date TEXT, coverage_pct REAL, low_alert REAL, high_alert REAL);
CREATE TABLE IF NOT EXISTS days ( date TEXT PRIMARY KEY, display_date TEXT, gmi_percent REAL, average_glucose REAL, time_in_range_pct REAL, sensor_usage_pct REAL );
CREATE TABLE IF NOT EXISTS glucose_readings ( id INTEGER PRIMARY KEY AUTOINCREMENT, date TEXT NOT NULL, hour INTEGER NOT NULL, minute INTEGER NOT NULL, value_mg_dl REAL NOT NULL, source TEXT DEFAULT "api", FOREIGN KEY (date) REFERENCES days(date) );
CREATE TABLE IF NOT EXISTS carb_intakes ( id INTEGER PRIMARY KEY AUTOINCREMENT, date TEXT NOT NULL, time TEXT NOT NULL, grams REAL NOT NULL, FOREIGN KEY (date) REFERENCES days(date) );
CREATE TABLE IF NOT EXISTS insulin_doses ( id INTEGER PRIMARY KEY AUTOINCREMENT, date TEXT NOT NULL, time TEXT NOT NULL, type TEXT NOT NULL CHECK (type IN ('rapid', 'long_acting')), units REAL NOT NULL, FOREIGN KEY (date) REFERENCES days(date) );
CREATE TABLE IF NOT EXISTS notes ( id INTEGER PRIMARY KEY AUTOINCREMENT, date TEXT NOT NULL, time TEXT NOT NULL, note_type TEXT NOT NULL, content TEXT, FOREIGN KEY (date) REFERENCES days(date) );
CREATE TABLE IF NOT EXISTS sync_metadata ( key TEXT PRIMARY KEY, value TEXT NOT NULL );
CREATE TABLE IF NOT EXISTS daily_metrics ( date TEXT PRIMARY KEY, average_glucose REAL, gmi_percent REAL, time_in_range_pct REAL, hypo_count INTEGER DEFAULT 0, hyper_count INTEGER DEFAULT 0, tir_count INTEGER DEFAULT 0, below_count INTEGER DEFAULT 0, above_count INTEGER DEFAULT 0, reading_count INTEGER DEFAULT 0, total_carbs REAL DEFAULT 0, total_insulin_rapid REAL DEFAULT 0, total_insulin_long REAL DEFAULT 0, insulin_rapid_doses INTEGER DEFAULT 0, insulin_long_doses INTEGER DEFAULT 0, carb_intake_count INTEGER DEFAULT 0, note_count INTEGER DEFAULT 0, cv_percent REAL, hypo_below_54 INTEGER DEFAULT 0, below_54_pct REAL DEFAULT 0, hypo_below_70 INTEGER DEFAULT 0, below_70_pct REAL DEFAULT 0, above_250_count INTEGER DEFAULT 0, above_250_pct REAL DEFAULT 0, above_180_count INTEGER DEFAULT 0, above_180_pct REAL DEFAULT 0, gmi_value REAL, ea1c_value REAL, tdd_rapid_units REAL DEFAULT 0, tdd_total_units REAL DEFAULT 0, carb_ratio REAL, insulin_sensitivity REAL, postprandial_peaks INTEGER DEFAULT 0, postprandial_avg_delta REAL, daily_range_mgdl REAL, median_glucose_mgdl REAL, mode_glucose_mgdl REAL, excursion_count INTEGER DEFAULT 0, mage REAL, dist_54_below_pct REAL DEFAULT 0, dist_54_to_70_pct REAL DEFAULT 0, dist_70_to_100_pct REAL DEFAULT 0, dist_100_to_140_pct REAL DEFAULT 0, dist_140_to_180_pct REAL DEFAULT 0, dist_180_to_250_pct REAL DEFAULT 0, dist_250_above_pct REAL DEFAULT 0, meal_count INTEGER DEFAULT 0, exercise_minutes INTEGER DEFAULT 0, capillary_reading_count INTEGER DEFAULT 0, capillary_avg_glucose REAL, pdf_daily_max_mgdl REAL, pdf_daily_min_mgdl REAL, rapid_insulin_units REAL DEFAULT 0, long_insulin_units REAL DEFAULT 0, rapid_injection_count INTEGER DEFAULT 0, max_single_rapid_dose REAL DEFAULT 0, insulin_correction_total REAL DEFAULT 0, insulin_correction_given REAL DEFAULT 0, insulin_meal_dose REAL DEFAULT 0, exercise_duration_minutes INTEGER DEFAULT 0, exercise_type TEXT, food_high_carb INTEGER DEFAULT 0, food_protein INTEGER DEFAULT 0, food_veggies INTEGER DEFAULT 0, food_dairy INTEGER DEFAULT 0, food_sweets INTEGER DEFAULT 0, food_fat INTEGER DEFAULT 0, FOREIGN KEY (date) REFERENCES days(date) );
CREATE TABLE IF NOT EXISTS hourly_patterns ( period_start TEXT NOT NULL, period_end TEXT NOT NULL, hour INTEGER NOT NULL CHECK (hour >= 0 AND hour <= 23), median_glucose REAL, p25_glucose REAL, p75_glucose REAL, p5_glucose REAL, p95_glucose REAL, avg_glucose REAL, reading_count INTEGER DEFAULT 0, avg_carbs REAL DEFAULT 0, total_carbs REAL DEFAULT 0, avg_rapid_insulin REAL DEFAULT 0, total_rapid_insulin REAL DEFAULT 0, rapid_dose_count INTEGER DEFAULT 0, avg_long_insulin REAL DEFAULT 0, total_long_insulin REAL DEFAULT 0, long_dose_count INTEGER DEFAULT 0, PRIMARY KEY (period_start, period_end, hour) );
CREATE TABLE IF NOT EXISTS sensor_usage ( id INTEGER PRIMARY KEY AUTOINCREMENT, period_start TEXT NOT NULL, period_end TEXT NOT NULL, total_readings INTEGER, total_days INTEGER, avg_readings_per_day REAL, coverage_pct REAL, recommended_readings_per_day REAL DEFAULT 86.4, FOREIGN KEY (period_start) REFERENCES days(date) );
CREATE TABLE IF NOT EXISTS weekly_summaries ( id INTEGER PRIMARY KEY AUTOINCREMENT, week_start TEXT NOT NULL, week_end TEXT NOT NULL, monday_date TEXT, avg_glucose REAL, hypo_events INTEGER DEFAULT 0, hyper_events INTEGER DEFAULT 0, total_carbs REAL DEFAULT 0, total_rapid_insulin REAL DEFAULT 0, total_long_insulin REAL DEFAULT 0, avg_grams_carbs REAL DEFAULT 0, avg_rapid_units REAL DEFAULT 0, avg_long_units REAL DEFAULT 0 );
CREATE TABLE IF NOT EXISTS weekly_daily_detail ( id INTEGER PRIMARY KEY AUTOINCREMENT, week_start TEXT NOT NULL, day_date TEXT NOT NULL, day_name TEXT, avg_glucose REAL, hypo_events INTEGER DEFAULT 0, hyper_events INTEGER DEFAULT 0, total_carbs REAL DEFAULT 0, total_rapid_insulin REAL DEFAULT 0, total_long_insulin REAL DEFAULT 0, FOREIGN KEY (day_date) REFERENCES days(date) );
CREATE TABLE IF NOT EXISTS alert_stats ( period_start TEXT PRIMARY KEY, period_end TEXT, sensor_usage_pct REAL, tir_pct REAL, tar_gt180_pct REAL, tar_gt250_pct REAL, tbr_lt70_pct REAL, tbr_lt54_pct REAL, tir_target_pct REAL, tar_target_pct REAL, tbr_target_pct REAL, avg_glucose_mg_dl REAL, gmi_pct REAL, a1c_pct REAL, cv_percent REAL, avg_glucose_target_mg_dl REAL, tir_lower REAL, tir_upper REAL, alarm_low_glucose REAL, alarm_high_glucose REAL );